pub fn vanilla_game_rule(resource_id: &str) -> Option<&'static GameRuleCatalogEntry> {
    VANILLA_GAME_RULES
        .iter()
        .find(|entry| entry.resource_id == resource_id)
}

#[cfg(test)]
mod tests {
    use std::{collections::HashSet, fs, path::Path};

    use super::*;

    #[test]
    fn game_rule_catalog_is_complete_unique_and_typed() {
        assert_eq!(VANILLA_GAME_RULES.len(), 59);
        let mut resource_ids = HashSet::new();
        for entry in VANILLA_GAME_RULES {
            assert!(resource_ids.insert(entry.resource_id));
            assert_eq!(vanilla_game_rule(entry.resource_id), Some(entry));
            assert!(matches!(
                entry.category,
                "chat" | "drops" | "misc" | "mobs" | "player" | "spawning" | "updates"
            ));
        }
        assert_eq!(vanilla_game_rule("minecraft:unknown"), None);
        assert_eq!(
            vanilla_game_rule("minecraft:keep_inventory")
                .unwrap()
                .value_kind,
            GameRuleValueKind::Boolean
        );
        assert_eq!(
            vanilla_game_rule("minecraft:fire_spread_radius_around_player")
                .unwrap()
                .value_kind,
            GameRuleValueKind::Integer {
                min: -1,
                max: i32::MAX
            },
        );
        assert_eq!(
            vanilla_game_rule("minecraft:max_snow_accumulation_height")
                .unwrap()
                .value_kind,
            GameRuleValueKind::Integer { min: 0, max: 8 },
        );
        assert_eq!(
            vanilla_game_rule("minecraft:max_minecart_speed")
                .unwrap()
                .value_kind,
            GameRuleValueKind::Integer { min: 1, max: 1000 },
        );
        assert_eq!(
            vanilla_game_rule("minecraft:keep_inventory")
                .unwrap()
                .category,
            "player"
        );
    }

    #[test]
    fn game_rule_values_parse_like_brigadier_and_apply_bounds() {
        let boolean = *vanilla_game_rule("minecraft:keep_inventory").unwrap();
        assert_eq!(
            boolean.parse_value("true"),
            Some(GameRuleValue::Boolean(true))
        );
        assert_eq!(
            boolean.parse_value("false"),
            Some(GameRuleValue::Boolean(false))
        );
        assert_eq!(boolean.parse_value("TRUE"), None);
        assert_eq!(boolean.parse_value(" true"), None);

        let snow = *vanilla_game_rule("minecraft:max_snow_accumulation_height").unwrap();
        assert_eq!(snow.parse_value("0"), Some(GameRuleValue::Integer(0)));
        assert_eq!(snow.parse_value("-0"), Some(GameRuleValue::Integer(0)));
        assert_eq!(snow.parse_value("08"), Some(GameRuleValue::Integer(8)));
        assert_eq!(snow.parse_value("-1"), None);
        assert_eq!(snow.parse_value("9"), None);
        assert_eq!(snow.parse_value("+1"), None);
        assert_eq!(snow.parse_value("1x"), None);
        assert_eq!(snow.parse_value("2147483648"), None);
        assert_eq!(GameRuleValue::Integer(8).serialize(), "8");
    }

    #[test]
    fn production_sources_do_not_redeclare_the_game_rule_catalog() {
        fn visit(directory: &Path, violations: &mut Vec<String>) {
            for entry in fs::read_dir(directory).unwrap() {
                let path = entry.unwrap().path();
                if path.is_dir() {
                    visit(&path, violations);
                    continue;
                }
                if path.extension().and_then(|value| value.to_str()) != Some("rs") {
                    continue;
                }
                let display = path.to_string_lossy();
                if display.ends_with("/game_rules.rs")
                    || display.ends_with("/tests.rs")
                    || display.contains("/tests/")
                {
                    continue;
                }
                let source = fs::read_to_string(&path).unwrap();
                let production = source.split("#[cfg(test)]").next().unwrap_or(&source);
                if production.contains("const VANILLA_GAME_RULES:") {
                    violations.push(display.to_string());
                }
            }
        }
        let mut violations = Vec::new();
        visit(
            Path::new(env!("CARGO_MANIFEST_DIR")).parent().unwrap(),
            &mut violations,
        );
        assert!(
            violations.is_empty(),
            "parallel game-rule catalog owners: {violations:?}"
        );
    }
}
